class CounterView extends ItemView {
  constructor(leaf, plugin) { super(leaf); this.plugin = plugin; this.signature = ""; }
  getViewType() { return VIEW_TYPE; }
  getDisplayText() { return "引用块统计"; }
  getIcon() { return "text-cursor-input"; }
  async onOpen() { this.contentEl.addClass("blockquote-counter-view"); this.plugin.scheduleRefresh(); }
  render(snapshot) {
    const signature = JSON.stringify([snapshot?.file.path, snapshot?.source, snapshot?.current?.index, this.plugin.settings]);
    if (signature === this.signature) return;
    this.signature = signature;
    const root = this.contentEl;
    root.empty();
    root.createEl("h3", { text: "引用块统计", cls: "bqc-header" });
    root.createDiv({ text: snapshot?.file.basename || "打开一篇 Markdown 笔记", cls: "bqc-subtitle" });
    root.createEl("p", { text: `每个引用框独立统计 · 上限 ${number(this.plugin.settings.limit)} 字符`, cls: "bqc-note" });
    if (!snapshot?.quotes.length) {
      root.createDiv({ text: "将需要统计的文字放在 > 引用框或 callout 中，输入后会实时显示字符数。", cls: "bqc-empty" });
      root.createEl("pre", { text: "## Writing excerpt\n\n> Write a short passage here.\n>\n> The next paragraph." });
      return;
    }
    const exceeded = snapshot.quotes.filter(q => this.plugin.count(q) > this.plugin.settings.limit).length;
    root.createDiv({ text: `${snapshot.quotes.length} 个引用框${exceeded ? ` · ${exceeded} 个超限` : " · 均在上限内"}`, cls: "bqc-summary" });
    for (const quote of snapshot.quotes) {
      const count = this.plugin.count(quote);
      const current = snapshot.current?.index === quote.index;
      const card = root.createDiv({ cls: `bqc-card ${this.plugin.level(count)}${current ? " bqc-current" : ""}` });
      const heading = card.createDiv({ cls: "bqc-card-header" });
      heading.createEl("strong", { text: quote.label, cls: "bqc-label" });
      heading.createSpan({ text: `#${quote.index}`, cls: "bqc-meta" });
      card.createDiv({ text: `${number(count)} / ${number(this.plugin.settings.limit)}`, cls: `bqc-count ${this.plugin.level(count)}` });
      const progress = card.createEl("progress", { cls: "bqc-progress" });
      progress.max = this.plugin.settings.limit;
      progress.value = Math.min(count, this.plugin.settings.limit);
      progress.setAttribute("aria-label", `${quote.label}：${count} 字符`);
      card.createDiv({ text: `${this.plugin.remaining(count)} · 第 ${quote.startLine + 1}–${quote.endLine + 1} 行`, cls: "bqc-meta" });
      card.createDiv({ text: `${quote.words} 词 · 去空白 ${number(quote.withoutWhitespace)}（UTF-16）`, cls: "bqc-meta" });
      if (quote.chars !== quote.codePoints) card.createDiv({ text: `UTF-16 ${number(quote.chars)} · Unicode 码点 ${number(quote.codePoints)}`, cls: "bqc-meta" });
      card.createDiv({ text: quote.text.replace(/\s+/g, " ").slice(0, 140) || "空引用框", cls: "bqc-preview" });
      const actions = card.createDiv({ cls: "bqc-actions" });
      const copy = actions.createEl("button", { text: "复制正文" });
      copy.addEventListener("click", () => this.plugin.copyFromSnapshot(snapshot, quote));
      const locate = actions.createEl("button", { text: "定位" });
      locate.addEventListener("click", () => this.plugin.locate(snapshot.file, quote));
    }
    root.createEl("p", { cls: "bqc-note", text: `计入空格、换行、Markdown 和公式源码；去掉外层 > 与 callout 标题。当前口径：${this.plugin.settings.countMode === "utf16" ? "UTF-16（保守）" : "Unicode 码点"}。复制按钮输出的正文与计数一致。` });
  }
}

class CounterSettings extends PluginSettingTab {
  constructor(app, plugin) { super(app, plugin); this.plugin = plugin; }
  display() {
    const root = this.containerEl;
    root.empty();
    root.createEl("h2", { text: "Blockquote Counter" });
    new Setting(root).setName("每个引用块的字符上限").setDesc("默认 2000；可按需要调整。")
      .addText(input => input.setValue(String(this.plugin.settings.limit)).onChange(value => {
        const parsed = Number(value);
        if (/^\d+$/.test(value) && Number.isSafeInteger(parsed) && parsed > 0) this.plugin.changeSettings({ limit: parsed });
      }));
    new Setting(root).setName("接近上限时提醒（%）").setDesc("默认用量达到 90% 时显示黄色，超过上限显示红色。")
      .addSlider(input => input.setLimits(50, 100, 1).setValue(this.plugin.settings.warningPercent).setDynamicTooltip()
        .onChange(value => this.plugin.changeSettings({ warningPercent: value })));
    new Setting(root).setName("字符计数口径").setDesc("英文和常用中文结果一致；UTF-16 将多数 emoji 计为 2，Unicode 码点计为 1。组合 emoji 可占多个码点。选择适合当前用途的计数方式。")
      .addDropdown(input => input.addOption("utf16", "UTF-16（默认，保守）").addOption("codepoints", "Unicode 码点")
        .setValue(this.plugin.settings.countMode).onChange(value => this.plugin.changeSettings({ countMode: value })));
    new Setting(root).setName("在引用框中显示字符数").setDesc("适用于编辑模式和阅读模式；仅显示提示，不写入笔记。")
      .addToggle(input => input.setValue(this.plugin.settings.inlineBadges).onChange(value => this.plugin.changeSettings({ inlineBadges: value })));
  }
}

module.exports = class BlockquoteCounter extends Plugin {
  async onload() {
    this.settings = normalizeSettings(await this.loadData());
    this.settingsVersion = 0;
    this.editorViews = new Set();
    this.readingBadges = new Map();
    this.lastMarkdownView = null;
    this.refreshToken = 0;
    this.disposed = false;
    this.registerView(VIEW_TYPE, leaf => new CounterView(leaf, this));
    this.addSettingTab(new CounterSettings(this.app, this));
    this.addRibbonIcon("text-cursor-input", "引用块统计", () => this.openPanel());
    this.addCommand({ id: "open-counter", name: "打开引用块统计", callback: () => this.openPanel() });
    this.addCommand({ id: "copy-current-block", name: "复制光标所在引用块正文", editorCallback: (editor) => {
      const line = editor.getCursor().line;
      const quote = parseQuotes(editor.getValue()).find(q => line >= q.startLine && line <= q.endLine);
      if (quote) this.copyQuote(quote); else new Notice("请先把光标放入一个 > 引用框。");
    } });
    this.status = this.addStatusBarItem();
    this.status.addClass("bqc-status");
    this.status.setAttribute("role", "button");
    this.status.setAttribute("tabindex", "0");
    this.registerDomEvent(this.status, "click", () => this.openPanel());
    this.registerDomEvent(this.status, "keydown", event => {
      if (event.key === "Enter" || event.key === " ") { event.preventDefault(); this.openPanel(); }
    });
    this.registerEvent(this.app.workspace.on("active-leaf-change", leaf => {
      if (leaf?.view instanceof MarkdownView) this.lastMarkdownView = leaf.view;
      else if (leaf?.view.getViewType() !== VIEW_TYPE) this.lastMarkdownView = null;
      this.scheduleRefresh();
    }));
    this.registerEvent(this.app.workspace.on("file-open", () => this.scheduleRefresh()));
    this.registerEvent(this.app.workspace.on("layout-change", () => this.scheduleRefresh()));
    this.registerEvent(this.app.workspace.on("editor-change", () => this.scheduleRefresh()));
    this.registerEvent(this.app.vault.on("modify", file => { if (file === this.lastMarkdownView?.file) this.scheduleRefresh(); }));
    this.registerEditorExtension(editorExtension(this));
    this.registerMarkdownPostProcessor((element, context) => this.decorateReading(element, context));
    this.app.workspace.onLayoutReady(() => { if (!this.disposed) this.scheduleRefresh(); });
  }

  count(quote) { return this.settings.countMode === "codepoints" ? quote.codePoints : quote.chars; }
  level(count) { return count > this.settings.limit ? "is-over-limit" : count >= this.settings.limit * this.settings.warningPercent / 100 ? "is-warning" : ""; }
  remaining(count) { return count > this.settings.limit ? `超出 ${number(count - this.settings.limit)} 字符` : `还可写 ${number(this.settings.limit - count)} 字符`; }
  paintBadge(element, quote) {
    const count = this.count(quote);
    element.className = `bqc-badge ${this.level(count)}`;
    element.textContent = `${number(count)} / ${number(this.settings.limit)} 字符`;
    element.setAttribute("title", `${this.remaining(count)}；含空格、换行与 Markdown 源码。`);
    element.setAttribute("aria-label", `${count} 字符，${this.remaining(count)}`);
    element.setAttribute("contenteditable", "false");
  }

  scheduleRefresh() {
    if (this.disposed) return;
    clearTimeout(this.refreshTimer);
    this.refreshTimer = setTimeout(() => this.refresh().catch(error => console.error("Blockquote Counter:", error)), 100);
  }
  async refresh() {
    const token = ++this.refreshToken;
    const active = this.app.workspace.getActiveViewOfType(MarkdownView);
    if (active) this.lastMarkdownView = active;
    const view = this.lastMarkdownView;
    let snapshot = null;
    if (view?.file && this.app.workspace.getLeavesOfType("markdown").some(leaf => leaf.view === view)) {
      const file = view.file;
      const editing = view.getMode() === "source";
      const source = editing ? view.editor.getValue() : await this.app.vault.cachedRead(file);
      const quotes = parseQuotes(source);
      const line = editing ? view.editor.getCursor().line : -1;
      snapshot = { file, source, quotes, current: quotes.find(q => line >= q.startLine && line <= q.endLine) };
    }
    if (token !== this.refreshToken || this.disposed) return;
    if (snapshot?.current) {
      const count = this.count(snapshot.current);
      this.status.setText(`引用 ${snapshot.current.index}：${number(count)} / ${number(this.settings.limit)}`);
      this.status.setAttribute("title", `${this.remaining(count)} · 点击查看所有引用框`);
      this.status.className = `status-bar-item bqc-status ${this.level(count)}`;
    } else {
      this.status.setText(snapshot?.quotes.length ? `引用：${snapshot.quotes.length} 个引用框` : "引用：无引用框");
      this.status.setAttribute("title", "点击打开引用块统计");
      this.status.className = "status-bar-item bqc-status";
    }
    for (const leaf of this.app.workspace.getLeavesOfType(VIEW_TYPE)) leaf.view.render(snapshot);
    for (const [element] of this.readingBadges) if (!element.isConnected) this.readingBadges.delete(element);
  }
  async openPanel() {
    let leaf = this.app.workspace.getLeavesOfType(VIEW_TYPE)[0];
    if (!leaf) {
      leaf = this.app.workspace.getRightLeaf(false);
      if (!leaf) return;
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    this.app.workspace.revealLeaf(leaf);
    this.scheduleRefresh();
  }
  async copyQuote(quote) {
    try {
      await navigator.clipboard.writeText(quote.text);
      new Notice(`已复制 ${number(this.count(quote))} 字符（不含外层 >）`);
    } catch (error) {
      console.error("Blockquote Counter: clipboard", error);
      new Notice("无法访问剪贴板，请在笔记中手动复制正文。");
    }
  }
  async copyFromSnapshot(snapshot, quote) {
    // Never copy outdated text during the editor's refresh debounce.
    // Do not guess a block's identity after an insertion or deletion shifts it.
    const view = this.app.workspace.getLeavesOfType("markdown").map(leaf => leaf.view)
      .find(candidate => candidate.file === snapshot.file && candidate.getMode() === "source");
    const source = view ? view.editor.getValue() : await this.app.vault.cachedRead(snapshot.file);
    if (source !== snapshot.source) {
      await this.refresh();
      new Notice("正文刚刚更新，统计已刷新，请再点击一次复制。");
      return;
    }
    await this.copyQuote(quote);
  }
  async locate(file, quote) {
    const existing = this.app.workspace.getLeavesOfType("markdown").find(leaf => leaf.view.file === file);
    const leaf = existing || this.app.workspace.getLeaf(false);
    await leaf.openFile(file, { active: true, state: { mode: "source" }, eState: { line: quote.startLine } });
    if (leaf.view instanceof MarkdownView) {
      leaf.view.editor.setCursor({ line: quote.startLine, ch: 0 });
      leaf.view.editor.scrollIntoView({ from: { line: quote.startLine, ch: 0 }, to: { line: quote.startLine, ch: 0 } }, true);
      leaf.view.editor.focus();
    }
  }

  async decorateReading(element, context) {
    const candidates = [...element.querySelectorAll("blockquote, .callout")].filter(node => !node.parentElement?.closest("blockquote, .callout"));
    if (!candidates.length) return;
    const file = this.app.vault.getAbstractFileByPath(context.sourcePath);
    if (!file || file.extension !== "md") return;
    const quotes = parseQuotes(await this.app.vault.cachedRead(file));
    if (this.disposed) return;
    const used = new Set();
    for (const container of candidates) {
      if (container.querySelector(":scope > .bqc-reading-toolbar, :scope > .callout-title > .bqc-reading-toolbar, :scope > .callout-title > [data-bqc-callout-badge]")) continue;
      const info = context.getSectionInfo(container);
      if (!info) continue;
      const quote = quotes.find(q => q.startLine >= info.lineStart && q.endLine <= info.lineEnd && !used.has(q.index));
      if (!quote) continue;
      used.add(quote.index);
      const toolbar = container.ownerDocument.createElement("div");
      toolbar.className = "bqc-reading-toolbar";
      const badge = container.ownerDocument.createElement("span");
      this.paintBadge(badge, quote);
      toolbar.appendChild(badge);
      toolbar.hidden = !this.settings.inlineBadges;
      const title = container.matches(".callout") ? container.querySelector(":scope > .callout-title") : null;
      if (title) title.appendChild(toolbar);
      else container.prepend(toolbar);
      this.readingBadges.set(badge, quote);
    }
  }

  async changeSettings(patch) {
    this.settings = normalizeSettings({ ...this.settings, ...patch });
    this.settingsVersion++;
    for (const view of this.editorViews) view.dispatch({ effects: settingsEffect.of(null) });
    for (const [element, quote] of this.readingBadges) {
      this.paintBadge(element, quote);
      element.parentElement.hidden = !this.settings.inlineBadges;
    }
    this.scheduleRefresh();
    await this.saveData(this.settings);
  }
  onunload() {
    this.disposed = true;
    clearTimeout(this.refreshTimer);
    this.refreshToken++;
    for (const [element] of this.readingBadges) element.parentElement?.remove();
    this.readingBadges.clear();
    this.app.workspace.detachLeavesOfType(VIEW_TYPE);
  }
};
